const rad=n=>n*Math.PI/180;
function between(a,b){const d1=rad(b.latitude-a.latitude),d2=rad(b.longitude-a.longitude),h=Math.sin(d1/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(d2/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
const distanceOf=pts=>pts.reduce((sum,p,i)=>i?sum+between(pts[i-1],p):sum,0);
const clock=s=>{s=Math.max(0,Math.floor(s||0));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),v=s%60;return h?[h,m,v].map(n=>String(n).padStart(2,"0")).join(":"):String(m).padStart(2,"0")+":"+String(v).padStart(2,"0");};
const pace=(s,m)=>m<30?"--:--":Math.floor(s/(m/1000)/60)+":"+String(Math.floor(s/(m/1000)%60)).padStart(2,"0");
function parseRoute(route){return Array.isArray(route)?route.map(p=>({latitude:Number(p.latitude??p.lat),longitude:Number(p.longitude??p.lng),at:Number(p.at||0),accuracy:Number(p.accuracy||0)})).filter(p=>Number.isFinite(p.latitude)&&Number.isFinite(p.longitude)):[];}
